import pandas as pdimport numpy as npimport warningsimport re# =============================================================================# # =============================================================================def sort_sample_id_abc(df):    """    Sort sample IDs naturally by prefix, number, and replicate.    Examples    --------    1_a, 1_b, 2_a, 10_a    C01_a, C01_b, C02_a, C19_c    M01_a, M02_a, M10_c    """    def sorting_key(sample_id):        sample_id = str(sample_id)        match = re.fullmatch(            r"([A-Za-z]*)(\d+)_([A-Za-z]+)",            sample_id        )        if match is None:            raise ValueError(                f"Invalid sample ID: '{sample_id}'. "                "Expected formats such as '1_a', 'C19_a', or 'M01_b'."            )        prefix, number, replicate = match.groups()        return (            prefix.lower(),            int(number),            replicate.lower(),        )    sorted_index = sorted(df.index, key=sorting_key)    return df.loc[sorted_index]# =============================================================================# # =============================================================================def align_data_metadata(df, df_meta):    """    Align a data matrix and metadata using sample indices.    Parameters    ----------    df : pandas.DataFrame        Data matrix with samples in rows and variables in columns.    df_meta : pandas.DataFrame        Metadata with samples in rows.    Returns    -------    df_aligned : pandas.DataFrame        Aligned data matrix.    df_meta_aligned : pandas.DataFrame        Aligned metadata.    """    missing_metadata = df.index.difference(df_meta.index)    missing_data = df_meta.index.difference(df.index)    if len(missing_metadata) > 0:        warnings.warn(            f"{len(missing_metadata)} samples have data but no metadata: "            f"{missing_metadata.tolist()}"        )    if len(missing_data) > 0:        warnings.warn(            f"{len(missing_data)} samples have metadata but no data: "            f"{missing_data.tolist()}"        )    common_samples = df.index.intersection(df_meta.index)    df_aligned = df.loc[common_samples].copy()    df_meta_aligned = df_meta.loc[common_samples].copy()    return df_aligned, df_meta_aligned##def crop_spectra(df, *regions):    """    Keep columns within one or more spectral regions.    Parameters    ----------    df : pandas.DataFrame        Spectral data with samples in rows and spectral-axis        values in columns.    *regions : tuple        One or more regions specified as (start, end).    Returns    -------    pandas.DataFrame        Spectral data containing only the selected regions.    Notes    -----    The input data are assumed to be cleaned and standardized.    This function does not sort or modify the spectral axis.    The original column order is preserved.    Usage    -----    Keep one NMR region:    >>> df_cropped = crop_spectra(df, (10, 0))    Keep two FTIR regions:    >>> df_cropped = crop_spectra(    ...     df,    ...     (3050, 2800),    ...     (1800, 600),    ... )    """    if len(regions) == 0:        raise ValueError(            "Provide at least one region, for example (10, 0)."        )    axis_values = df.columns.astype(float).to_numpy()    mask = np.zeros(len(axis_values), dtype=bool)    for region in regions:        if len(region) != 2:            raise ValueError(                "Each region must contain exactly two values."            )        low, high = sorted(region)        mask |= (            (axis_values >= low)            & (axis_values <= high)        )    if not mask.any():        raise ValueError(            "No spectral columns were found within the selected regions."        )    return df.loc[:, mask].copy()##def compare_sample_ids(df1, df2):    """    Find sample IDs that differ between two DataFrames.    Parameters    ----------    df1, df2 : pandas.DataFrame        DataFrames with sample IDs in their indexes.    Returns    -------    dict        Sample IDs found only in each DataFrame.    Usage    -----    >>> differences = compare_sample_ids(df1, df2)    >>> print(differences)    """    return {        "only_in_df1": df1.index.difference(df2.index).tolist(),        "only_in_df2": df2.index.difference(df1.index).tolist(),    }